INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('advanced-guide-to-airbrush-colors', 'bill', 'Great info here. I''m new to airbrushing and i have a question about colours. If i acquire several big (30ml) external gravity feed cups for each paint, can i keep the acrylics or inks inside them when i finish working? It would be very convenient if i didn''t have to measure how much paint i want each time and just remove the cup from the airbrush and store the colour away for future use. I mean, are cups properly sealed as to not allow air to dry them up?', 'approved', 'wp-import', '2014-04-23 12:33:00');
