INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('advanced-guide-to-airbrush-colors', 'Jutah', 'Hi. First of all, this blog is awesome. It included tons of the info I needed. Thanks so much! I just started using Createx opaque paint with my Iwata Revolution BCR and although the bottle says it should work on the 5 mm. tip, the paint flow is much slower and way less bright than my previous paint. I would greatly appreciate if you could help me figure out the problem. Thanks.', 'approved', 'wp-import', '2018-05-13 04:23:30');
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('advanced-guide-to-airbrush-colors', 'nizam', 'hello sir, i''m starting new hobby of painting my casio g-shock watches. could you give me any pointer on what types of paint should i use? most of the g-shock use resin material. i would like to paint it permanently. any tips on how to make that paint crack resist and scratch resist? thank you in advance. cheers.', 'approved', 'wp-import', '2018-05-13 22:48:47');
