INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('advanced-guide-to-airbrush-colors', 'Joe Fleming', 'Really good article.  Thanks
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('advanced-guide-to-airbrush-colors', 'VicSee', 'The breakdown by paint type is really useful — didn''t realize solvent-based and water-based behave so differently when layering. The note about automotive paints needing careful thinning ratios is a good heads up for beginners.', 'approved', 'wp-import', '2026-03-23 02:19:33');
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('advanced-guide-to-airbrush-colors', 'emergency hvac repair', 'The distinction between water-based and solvent-based paints is so important to get right early on. Switching mid-project because of adhesion issues on a particular surface is a frustrating lesson that most airbrush beginners learn the hard way.', 'approved', 'wp-import', '2026-04-14 05:18:49');
