INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('airbrush-car-in-photoshop', 'Melody', 'Wow, that is so cool. I remember the day I came home and found my mate had put rubber flowers decals all over my 1966 Mustang. That was a long time ago, but I remember being not best pleased. At that time the decals were it, and then they began painting flames on the sides of hot cars. Things have certainly changed for the better.', 'approved', 'wp-import', '2011-05-21 21:25:00');
