INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('harder-and-steenbeck-infinity-review', 'WeatherVane', 'I have a nice Harder & Steenbeck Infinity 2 in 1 that only sprays air (plenty of air)  NO liquid .. l.  No liquid.  Great air brush.(sprays air)  Precision workmanship. Precision parts. Nice trigger.  Nice feel. Sprays AIR .(LOL)   I  have had it for quite some time; bought all kinds of stuff for it but (guaranteenot honored .. the dealer never heard of me)(hence buy it on credit and return via the credit card)  (I just checked the bill) IT WAS $300 (wasted) . plus the motor (Model AS180 and Testor blue motor too .. $210 for motors)  and all of the paints (it does not spray) .. $75 ..but they did not say "paint brush" they said "air brush."  It sprays air!.     Maybe i could make it into a shadow box for the wall.    If anyone learns how to make the H&S airbrush spray liquid onto a surface kindly share how you got it to work.', 'approved', 'wp-import', '2014-08-25 22:40:00');
