INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('harder-and-steenbeck-infinity-review', 'chris', 'You can make any conventional airbrush spatter without buying a spatter cap. Turn down the air pressure so that the paint only just comes out of the airbrush. It should give a rather wide, irregular line. Then pull back the trigger all the way, quickly lift the index finger to release it, letting the spring push it back into the rest position. Depending on the water : paint mix ratio (I use between 10 : 1 and 20 : 1) you should get a controllable spatter pattern. You could do it as quick as you read, tic, tic, tic in this line to cover small or large areas with spattering. The lower the air pressure, the bigger the spatter droplets will be.
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('harder-and-steenbeck-infinity-review', 'Mike Littlefield', 'You can purchase a spatter cap for all the Harder & Steenbeck airbrushes.  You can go to www.precisiongermanairbrush.com to find what you want.  You can also go to www.germanairbrush.com to find all the dealers.', 'approved', 'wp-import', '2012-08-24 22:30:00');
