INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('harder-and-steenbeck-infinity-review', 'Dave Wyatt', 'Hello Sergi,  Looks like I am 7 year late reading this, I have 2 each H&S infinitys and a lot of other Airbrushes, The Infinity is my Go-To Airbrush for super fine details, If I had known what I do now I doubt I would have bought any other (well maybe I would because there are some nice airbrushes). Still I would put it even with the Iwata Micron as far as performance and both the airbrush and it''s parts are much less expensive.', 'approved', 'wp-import', '2018-09-01 02:03:30');
