INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('harder-and-steenbeck-infinity-review', 'William Bigelow', 'I have this airbrush.  Problem - longevity of nozzle and gaskets.  I also have a Evolution by the same manufacture.  Bubble blow back after what I consider little use on three of the four nozzle/needle sets I have and a fourth that barely works.  Sizes: .15, two .4 and one .6mm.  I replaced the gaskets at cost $13.00 plus shipping, enough for two.  To no avail. What can be done? Their little manual says also replace the Nozzles!  Another expense. Has anyone heard of any other solution?  Greatly appreciated.', 'approved', 'wp-import', '2023-11-26 17:10:44');
