INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('how-to-make-a-stencil-in-coreldraw', 'SilverScreen aka Per Corell', 'Hi, either you have a driver that you set as a printer in Windows, or you use the Gimp Export options ad export the drawing in a format that you can load in your Plotter program. Much of this Vector making, are about exporting and importing and not all programs open all exported files.
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('how-to-make-a-stencil-in-coreldraw', 'SilverScreen aka Per Corell', 'There are cutter plotter drivers for CorelDraw, but there are so many misunderstandings about what plotters can, -- many don''t know the difference between a Plotter and a Printer. I use the ArtCUT program that came with my plotter, not to draw in but for importing DXF files I made in AutoCAD as Line drawings, as ArtCUT are the perfect program to run a cutter plotter, it even expand the work area automatic and tell what sizes you need to feed into the plotter, and then it calculate the individual plots so you can stitch several sheets into one, if you need a huge Stencil. --- Btw. do not use paper in a Vinyl plotter, it will blond your knive very fast.', 'approved', 'wp-import', '2016-05-04 13:24:00');
