INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('how-to-make-layered-stencil-in-coreldraw', 'Nico', 'Sergej, I am now able to do it like a pro ! thanks. But now I have another question : Is it possible to select a range of colour on a coloured picture like the one above, for example red and close, and make corel select these colours automatically (it would be the dress and lips for that example) ? I think It would much easier than using the threshold option which needs a lot of tests and avoid to select twice the same part of the picture... I hope you understand what I mean, I know my English is a little bit poor to explain such subject...', 'approved', 'wp-import', '2012-01-29 21:55:00');
