INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('master-airbrush-review', 'bob', 'With a careful eye and patience you can file the hole so that it''s centered. I have 3 of these airbrushes and have spent days dialing them in. They are now AMAZING,very responsive and will do a hairline so small its incredible. I use dremel diamon bits to carefully fix the hole so that its centered. Do this by hand with the bit and not using the dremel!!!! It takes a while but its worth it. Finish up by carefully polishing the face of the cap with a rubberized abrasive polishing wheel.', 'approved', 'wp-import', '2014-09-03 20:09:00');
