INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('master-airbrush-review', 'Sergej Voronko', 'Yep, I agree with you guys.  Cheap airbrush will save some money but just from the start. Then you just spend more money trying to find something better or in worst case will drop the whole thing - airbrushing.', 'approved', 'wp-import', '2012-03-28 10:09:00');
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('master-airbrush-review', 'meanas', 'buy the top brands don''t waste your time with cheap air brushes, we all want to create fine art work save your money buy an Iwata sell some art work on line buy anther, with the right tools can produce some really fine and sick art work.', 'approved', 'wp-import', '2012-03-28 00:11:00');
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('master-airbrush-review', 'Hans', 'Thanks for the great review which could help many to save wasting $, preserve the joy of airbrushing & perhaps protect the environment by reducing waste.
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('master-airbrush-review', 'Kevin Ekstrom', 'Well, the truth is these are not sold or marked for the professional. These airbrushes are cheap alternatives for the casual user who needs something dirt cheap. I know I wasn''t expecting quality from this gun, and the price dictates I will get what I pay for. I wanted this brush to use for some quick primer work and it handled the job fine. I''m not sure what others are thinking when buying an item as this, but do the research before you buy anything. To be honest, at 30.00 USD, what do you expect? REALLY? It''s not like your out a bundle if you buy a cheap knock-off, but be aware, it is intended to be used by those needing a cheap alternative.', 'approved', 'wp-import', '2016-03-06 18:20:00');
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('master-airbrush-review', 'Sergej Voronko', 'Thank you for constructive feedback Kevin.', 'approved', 'wp-import', '2016-03-08 09:15:00');
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('master-airbrush-review', 'Larry Griffin', 'They are made in China.  I have two. For about $21 to $35 apiece.  Are they any good? They are for the beginner. The factory also makes Iwata believe it or not.  Of course for a lot more money.  Sometimes you may get a bent needle and contacting the company is pretty much useless.  I know I got one. The other two are good though and work well.', 'approved', 'wp-import', '2017-01-08 10:19:00');
