INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('airbrush-compressor-as189-review', 'Sergej Voronko', 'Yep, Paasche VL is a hungry beast. Exactly as you mentioned it isn''t that precise as Iwata, because of the nozzle sizes, and that''s why it needs something more powerful than this small Chinese dude ;)', 'approved', 'wp-import', '2012-10-19 21:55:00');
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('airbrush-compressor-as189-review', 'André van Wyk', 'I had one of those. The local distributors just placed it''s name on the box and and side. It started of great until I needed more power. And by more I mean 25psi. To run at that pressure it needs to run the whole time. So after 40 minutes of running it cuts out and you have to wait 30 minutes for it to cool down enough to continue. I sold it to a model builder and he is very happy with it. they only need to paint for short stints so it actually never gets too hot. Stay away from a compressor with the words "airbrush compressor" on the box.', 'approved', 'wp-import', '2012-10-19 10:17:00');
