INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('paasche-talon', 'ArtisticWildlife Taxidermist', 'I purchased one of these almost two years ago, it has become my go to airbrush. I also have a couple high priced Iwatas, that have taken a back shelf to the Talon. The Talon is most forgiving, I use lacquer paints and some acrylic water borne paints. The airbrush preforms almost flawlessly each and everytime without serious maintenance.', 'approved', 'wp-import', '2013-08-21 12:05:00');
