INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('paasche-talon', 'Mark Nagornyi', 'Hi Sergej! I never use airbrush before and painted my models by the brushes. Now I want to make the perfect model of Mi-24 1:72 and try to choose a good airbrush. All people recommended to buy IWATA HP-C Plus. However price for full set will be too much. I look for the Paasche Talon TG-3F Set from chicagoairbrushsupply but there are a lot of negative reviews in internet. Some people said that trigger is too hard. I hope that Paasche solved this issue as they said that "The trigger and air valve have been redesigned to allow for a smoother stroke as well as ease of assembly and durability". What do you know about this?', 'approved', 'wp-import', '2016-01-29 07:34:00');
