INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('best-airbrush', 'Garry', 'Last year I bought a Talon siphon feed to replace my VLs only to discover the front end feels heavy to me, however its spray control along with interchangeable tips are positive features. I like my Iwata BCS for its balance and spray control, as the Millenium is slimmer than the other Paasche ABs maybe that would have been a better choice.
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('best-airbrush', 'SilverScreen', 'Yes we agree, still it''s better to take apart a cheap Chinese to get the feel of how an airbrush work. Better than taking apart your most expensive, before you ever tried taking one apart.', 'approved', 'wp-import', '2012-11-19 22:01:00');
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('best-airbrush', 'Sergej Voronko', 'Good one Per! This is also truth. But beginners have to be careful, especially with cheapest tools because they are much more easier to break than the expensive ones.', 'approved', 'wp-import', '2012-11-19 22:33:00');
