INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('paasche-talon-problem', 'Javier', 'My Talon is very good and I have no problem with it. The trigger is a little hard to push down and it maintains pressed alone. How may I sandpaper it to fix this disappointment?', 'approved', 'wp-import', '2013-07-09 02:12:00');
