INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('paasche-talon-problem', 'Dave', 'I own a Talon TG. I bought it the very day they came out on the market. It came in a foam lined black plastic case. It came with .25 tip and needle only. The tigger pull was a little rough. Nothing a little bit of sanding with fine wet and dry sandpaper didn''t fix. I''ve owned it now for a few years and have been very happy with it. The chrome has worn away in some spots, but still performs excellent. I now own many airbrushes from many different companies. The Talon still holds its own and I find myself using it often. Maybe since it was hot off the press is why faulty quality was not an issue for me. Assuming Paasce wanted to make a good first impression with a new airbrush model. I doubt Id buy a second one because of the many bad reviews and unhappy customers ive read and heard.', 'approved', 'wp-import', '2013-02-23 01:11:00');
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('paasche-talon-problem', 'Sergej Voronko', 'Hey Dave, Thank you very much for comment. I think that maybe you are right that they wanted to make a good impression. I''m happy with my Talon too. 
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('paasche-talon-problem', 'Sergej Voronko', 'Thanks for your addition Andy, it means a lot for all of us. I see that there is more people that don''t like Talon then are actually satisfied with it.', 'approved', 'wp-import', '2013-02-06 19:48:00');
INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('paasche-talon-problem', 'andy', 'Mine talon was all bad as well it spray a line and the finish came off I will never buy from these hill Billy''s again', 'approved', 'wp-import', '2013-02-05 21:30:00');
