INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('what-is-my-art-worth', 'Steven Lane', 'I guess you also have to look at the customer as well. Will it be worth your while if you charge less on a good piece if they will bring you more business. After a while it will be easier to read a client so you know exactly who will be a long standing loyal client and who will be a one hit wonder. As a graphic designer i was able to learn this and I use it for my paintings as well.', 'approved', 'wp-import', '2012-12-14 21:48:00');
