INSERT INTO comments (slug, author, body, status, ip_hash, created_at) VALUES ('airbrush-infographic', 'Frank Gavere', 'Acrylics, when applied to proper substrates should outlast most paints;their thin flexible films have the ability to flex,& a great binder system.Use a quality brand; & I think your good to go for decades.Otherwise fine article.', 'approved', 'wp-import', '2014-03-27 11:47:00');
